// Minimal Cosmic Dodge game implementation
// Assumes an HTML canvas element with id="game" is present.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');

  const W = canvas.width;
  const H = canvas.height;

  // Player ship
  const ship = {
    x: 50,
    y: H / 2,
    w: 20,
    h: 20,
    speed: 4,
    dy: 0,
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y - this.h / 2);
      ctx.lineTo(this.x - this.w / 2, this.y + this.h / 2);
      ctx.lineTo(this.x + this.w / 2, this.y + this.h / 2);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      this.y += this.dy;
      // keep inside canvas
      if (this.y - this.h / 2 < 0) this.y = this.h / 2;
      if (this.y + this.h / 2 > H) this.y = H - this.h / 2;
    },
  };

  // Obstacles (asteroids)
  const asteroids = [];
  const asteroidSpeed = 3;
  const spawnInterval = 1500; // ms
  let lastSpawn = 0;

  function spawnAsteroid() {
    const size = 20 + Math.random() * 30;
    const y = Math.random() * (H - size) + size / 2;
    asteroids.push({ x: W + size, y, w: size, h: size });
  }

  // Input handling
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowUp') ship.dy = -ship.speed;
    else if (e.key === 'ArrowDown') ship.dy = ship.speed;
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowUp' || e.key === 'ArrowDown') ship.dy = 0;
  });

  // Score
  let score = 0;
  let startTime = null;
  let gameOver = false;

  function drawScore() {
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  }

  function checkCollision(a, b) {
    return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  function gameLoop(timestamp) {
    if (!startTime) startTime = timestamp;
    const delta = timestamp - (lastSpawn || timestamp);
    if (delta > spawnInterval) {
      spawnAsteroid();
      lastSpawn = timestamp;
    }

    ctx.clearRect(0, 0, W, H);

    // Update and draw ship
    ship.update();
    ship.draw();

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x -= asteroidSpeed;
      ctx.fillStyle = '#aaa';
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.w / 2, 0, Math.PI * 2);
      ctx.fill();

      // Collision
      if (checkCollision(ship, { x: a.x - a.w / 2, y: a.y - a.h / 2, w: a.w, h: a.h })) {
        gameOver = true;
      }

      // Remove off‑screen
      if (a.x + a.w < 0) asteroids.splice(i, 1);
    }

    // Score based on time survived
    if (!gameOver) score = (timestamp - startTime) / 1000;
    drawScore();

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f00';
      ctx.font = '24px monospace';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    } else {
      requestAnimationFrame(gameLoop);
    }
  }

  requestAnimationFrame(gameLoop);
})();
